//! 🛫️ The actual Source admits one exact byte backing and every write span before a caller-owned receiver changes.
use super::*;
use semio_framework_value::native_encoding::{NativeEncodeControl,NativeEncodeAllocation};
use std::cell::{Cell,RefCell};
struct EncodingEffectReceipt<'turn>{context:*mut StepContext<'turn>,output:*const Option<Vec<u8>>,planned:*const Cell<Option<usize>>,permits:*const Cell<usize>,start:RetainedCloneProgress,settled:bool}
impl EncodingEffectReceipt<'_>{
 fn settle(&mut self)->(RetainedCloneProgress,Option<ValueError>,Option<ValueError>){let cx=unsafe{&mut*self.context};let output=unsafe{&*self.output};let planned=unsafe{&*self.planned};let permits=unsafe{&*self.permits};let capacity=output.as_ref().map_or(0,Vec::capacity);let copied=output.as_ref().map_or(0,Vec::len);let provenance=if output.is_some()&&(planned.get()!=Some(capacity)||copied>permits.get()){Some(encoding_refusal("Source byte receiver differs from its admitted physical backing or writes"))}else if output.is_none()&&permits.get()!=0{Some(encoding_refusal("Source byte receiver lost its admitted partial backing"))}else{None};let receipt=cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copied,retained_capacity_bytes:capacity,..Default::default()});cx.consume_fuel(1);self.settled=true;(retained_delta(cx.retained_progress(),self.start),receipt.err(),provenance)}
}
impl Drop for EncodingEffectReceipt<'_>{fn drop(&mut self){if !self.settled{self.settle();}}}
impl StepContext<'_>{
 /// 🎟️ See `README.md`.
 pub fn with_native_encoding(&mut self,output:&mut Option<Vec<u8>>,encode:impl FnOnce(&mut NativeEncodeControl<'_>,&mut Option<Vec<u8>>)->Result<(),ValueError>)->Result<(),OriginalTurnFailure>{
  self.original_source_parent()?.validate_borrowed_context(self)?;if output.is_some(){return Err(encoding_refusal("Source encoding requires an empty original byte receiver").into())}if self.should_yield()||self.is_cancelled()||self.fuel_remaining()<2||self.retained_grant().maximum_items<2||self.retained_grant().maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source encoding requires its funded live work and receiver metadata").into())}
  let start=self.retained_progress();let identity=OriginalSourceBinding::borrow(self);self.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;self.consume_fuel(1);
  let planned=Cell::new(None::<usize>);let copy_permits=Cell::new(0usize);let maximum=self.retained_grant().maximum_capacity_bytes;let depth=self.retained_grant().maximum_depth;let mut receiving=EncodingEffectReceipt{context:std::ptr::addr_of_mut!(*self),output:output as*const _,planned:&planned,permits:&copy_permits,start,settled:false};let source=RefCell::new(&mut*self);
  let mut observer=|_:semio_framework_value::native_encoding::NativeEncodeProgress|{let source=source.borrow();identity.matches(&source)&&!source.should_yield()&&!source.is_cancelled()};
  let mut allocate=|request:NativeEncodeAllocation|{let source=source.borrow();if !identity.matches(&source)||source.should_yield()||source.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"Source byte allocation no longer has its admitting work"))}if planned.get().is_some()||request.owned_bytes!=0||request.bytes!=request.next_owned_bytes||request.bytes>source.retained_grant().maximum_capacity_bytes||source.retained_grant().maximum_items==0{return Err(encoding_refusal("Source byte encoding requires one exact admitted backing"))}planned.set(Some(request.bytes));Ok(())};
  let mut work=|units:usize,owned:usize|{let mut source=source.borrow_mut();if !identity.matches(&source)||source.should_yield()||source.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"Source byte span no longer has its admitting work"))}let fuel=u64::try_from(units).map_err(|_|encoding_refusal("Source byte span exceeds its work representation"))?;if fuel>source.fuel_remaining().saturating_sub(1){return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source byte span exceeds remaining work"))}if owned!=0{if planned.get()!=Some(owned){return Err(encoding_refusal("Source byte span changed its admitted backing"))}let copied=copy_permits.get().checked_add(units).ok_or_else(||encoding_refusal("Source byte span extent overflow"))?;if copied>source.retained_grant().maximum_copy_bytes{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"Source byte span exceeds remaining copy currency"))}copy_permits.set(copied);}source.consume_fuel(fuel);Ok(())};
  let mut control=NativeEncodeControl::new_scoped_source(maximum,depth,&mut observer,&mut allocate,&mut work);let result=encode(&mut control,output);drop(control);drop(work);drop(allocate);drop(observer);drop(source);
  let (effects,receipt,provenance)=receiving.settle();let primary=result.err().or(provenance);match(primary,receipt){(None,None)=>Ok(()),(primary,receipt)=>{let mut failure=OriginalTurnFailure::from(primary.unwrap_or_else(||encoding_refusal("Source encoding retained its rejected receiving receipt")).with_retained_progress(effects));failure.receipt_refusal=receipt;if !identity.matches(self){failure.context_refusal=Some(encoding_refusal("Source encoding changed its original recipient"));}Err(failure)}}
 }
}
fn encoding_refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
